contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single test function: attempts to lock a guess with a provided amount and then
    // asserts that if the guess was recorded (indicated by address(c).balance increased by that amount),
    // then the amount must be exactly 1 ether.
    function runTest(uint96 deposit, bytes32 h) public payable {
        // ensure this contract has enough balance to send
        require(address(this).balance >= deposit, "not enough balance for deposit");

        // record contract balance before call
        uint balBefore = address(c).balance;

        // call lockInGuess with provided deposit
        c.lockInGuess{value: deposit}(h);

        // observe contract balance after call
        uint balAfter = address(c).balance;

        // If the call caused the target contract's balance to increase (meaning it accepted and stored the guess),
        // then the deposit must have been exactly 1 ether. This distinguishes the original (requires 1 ether)
        // from the mutant (requires 2 ether), because for the same deposit the balance change differs.
        assert(!(balAfter > balBefore) || deposit == 1 ether);
    }

    // allow the test contract to receive ETH so tests can fund it
    receive() external payable {}
}

