    function run(uint amount, bytes32 hash) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        try c.lockInGuess{value: amount}(hash) { reverted = false; } catch { reverted = true; }
        // On the original contract, lockInGuess succeeds exactly when amount == 1 ether.
        assert(reverted == (amount != 1 ether));
    }
    receive() external payable {}
}

