pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzzed params: actor address and two distinct guess hashes
    function testFuzz_property(address actor, bytes32 h1, bytes32 h2) public {
        vm.assume(actor != address(0)); // keep actor meaningful
        // ensure different guesses to expose overwrite
        vm.assume(h1 != h2);

        // fund actor so they can send 1 ether
        vm.deal(actor, 2 ether);

        // Actor locks in first guess
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h1);

        // read stored guess and block value after first lock
        (/* blockNum1 not directly accessible via tuple since struct not public; use call to settle behavior instead */) ;

        // advance one block so settle would be allowed for first guess's block
        vm.roll(block.number + 2);

        // Now actor locks in a second guess. In the correct contract this should revert/prevent because a guess was active
        // But since the reference uses a require(guesses[msg.sender].block == 0) it will not allow replacing until settled.
        // We detect overwrite by attempting to settle: if overwrite happened, settle will use the new guess and may pay out differently.

        // Call settle and capture whether it succeeds (i.e., does not revert) and observe contract balance change
        // Record balance before second lock
        uint balBefore = address(c).balance;

        vm.prank(actor);
        bool okSecondLock;
        try c.lockInGuess{value: 1 ether}(h2) {
            okSecondLock = true;
        } catch {
            okSecondLock = false;
        }

        // After attempting second lock, call settle to clear any pending guess for actor (if any)
        vm.prank(actor);
        bool okSettle;
        try c.settle() {
            okSettle = true;
        } catch {
            okSettle = false;
        }

        uint balAfter = address(c).balance;

        // General rule: In the correct contract, the second lockInGuess call MUST fail (okSecondLock == false) because actor already had an active guess,
        // and therefore settle cannot be called to collect again (okSettle will be either false or will not have paid out 2 ether unexpectedly). The mutant that allows overwrite
        // will make okSecondLock true for some inputs (here when h1 != h2) and may change balances.
        // We assert that okSecondLock == false (the correct contract enforces no overwrite); this will hold on reference for all inputs,
        // and the mutant (which removed the guard) will allow overwrite for some inputs causing the assertion to fail.
        assertTrue(!okSecondLock);
    }
}

