pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzzed params: an address (the caller) and two different guess hashes
    function testFuzz_property(address caller, bytes32 hash1, bytes32 hash2) public {
        // keep caller non-zero and distinctness of hashes wide but meaningful
        vm.assume(caller != address(0));
        vm.assume(hash1 != hash2);

        // fund and act as caller
        vm.deal(caller, 2 ether);

        // first lockInGuess: should succeed on reference and set stored guess and block
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(hash1);

        // read stored guess and block via public getter: guesses is not public in C, but we can
        // observe behavior by attempting another lockInGuess and then deducing whether overwrite occurred
        // The reference requires callers with an active guess cannot call lockInGuess again (it reverts).
        // So we try a second lockInGuess and capture whether it reverted (ok=false) or succeeded (ok=true).
        bool ok;
        vm.prank(caller);
        try c.lockInGuess{value: 1 ether}(hash2) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for any inputs, the correct contract will reject the second lockInGuess (ok == false).
        // The mutant that removed the no-existing-guess check will allow the second call (ok == true) for some inputs.
        assertTrue(!ok);
    }
}

