pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzz the caller address (actor). The rule: after lockInGuess succeeds, guesses(actor).block > block.number at the moment immediately after the call.
    function testFuzz_property(address actor, bytes32 hash) public {
        // admissible: actor must be nonzero and distinct from the test contract to simulate external caller
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // give the actor exactly 1 ether so they can call
        vm.deal(actor, 1 ether);

        // prepare the call as the actor
        vm.prank(actor);
        bool ok;
        // perform the payable call and capture whether it succeeded
        try c.lockInGuess{value: 1 ether}(hash) {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call succeeded, the correct contract guarantees the stored block for actor is strictly greater than the block at which the lockInGuess returned.
        // We read the public mapping via the auto-generated getter: guesses(address) returns (uint block, bytes32 guess)
        (uint storedBlock, bytes32 storedGuess) = c.guesses(actor);

        // Single assertion: for any successful lockInGuess call, storedBlock > current block (i.e. the stored block is a future block).
        // This holds for the reference implementation (which stores block.number + 1) for all inputs, but the mutant that stores block.number will sometimes store storedBlock == block.number, making this assertion fail for some fuzzed inputs.
        assertTrue(!ok || (storedBlock > block.number));
    }
}

