import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzz the caller and the guess so the fuzzer can find cases where a mutant would pay out in the same block
    function testFuzz_property(address actor, bytes32 guess) public {
        // admissible domain: actor must be non-zero and distinct from this contract to be a realistic caller
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // fund the actor so they can send 1 ether
        vm.deal(actor, 2 ether);

        // record contract balance before the interactions
        uint256 before = address(c).balance;

        // have the actor call lockInGuess with exactly 1 ether in the current block
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // Immediately call settle in the same block as lockInGuess (no vm.roll/vm.warp between calls).
        // If the reference is correct, settle cannot pay out in the same block (it requires block.number > stored)
        // so contract balance must remain unchanged. The mutant that stored block.number can allow a payout
        // in the same block for certain guesses (when blockhash(...) equals the guess) and thus reduce balance.
        // We perform the settle call from the same actor.
        vm.prank(actor);
        // catch any revert to ensure we always observe balance after attempted settle
        try c.settle() {
            // no-op
        } catch {
            // revert is acceptable; still check balance
        }

        uint256 after = address(c).balance;

        // Single assertion: in the correct contract, calling settle in the same block after lockInGuess
        // never reduces the contract balance. The mutant may reduce it for some inputs; thus this assertion
        // should hold for the reference for all fuzz inputs and fail on the mutant for some.
        assertTrue(after >= before);
    }
}

