    C c;

    function setUp() public { c = new C(); }

    // fuzz the actor and the submitted hash; for any actor and any non-zero hash,
    // after a successful lockInGuess call with exactly 1 ether the stored guess
    // for that actor must equal the submitted hash (the mutant that clears it
    // will make the stored guess zero and thus violate this property).
    function testFuzz_property(address actor, bytes32 submitted) public {
        vm.assume(actor != address(0)); // keep actor meaningful

        // must send exactly 1 ether per contract requirement
        uint256 amt = 1 ether;

        // fund the actor so they can send 1 ether
        vm.deal(actor, amt);

        // actor calls lockInGuess with the fuzzed submitted hash and 1 ether
