        // We assert that for ALL inputs: if submitted != 0 then storedGuess == submitted.
        // The mutant that clears the guess will make storedGuess == 0 for such inputs,
        // causing this assertion to fail for some fuzz inputs.
        if (submitted != bytes32(0)) {
            assertTrue(storedGuess == submitted);
        } else {
            // when submitted is zero, stored guess may be zero; accept that.
            assertTrue(true);
        }
