        vm.roll(B + 1);
        // Now block.number == B+1, blockhash(B+1) is blockhash of current block which is non-zero only when read in later blocks.
        // We need to obtain blockhash(B+1) as a bytes32 value to pass into lockInGuess called at block B.
        // But we cannot call lockInGuess in a past block. So instead choose plan: call lockInGuess at current block (call it X), so lockedBlock = X+1,
        // then advance one block so blockhash(lockedBlock) is readable and equal to blockhash(X+1).

        // Simpler deterministic strategy:
        // - Let actor call lockInGuess now (at block number N). lockedBlock = N+1.
        // - Advance by offset+1 so that when settle is called, block.number > lockedBlock and blockhash(lockedBlock) is available.
        // - Before calling lockInGuess, compute the guess value we want: we can read blockhash(lockedBlock) only after that block exists; but since lockedBlock will be N+1,
        //   we can set guess later by re-deploying and repeating — instead we will craft the test to assert a relation that must always hold for reference:
        // The reference contract compares storedGuess to blockhash(lockedBlock). Therefore, after calling lockInGuess and then settle, the boolean (didPay) equals (storedGuess == blockhash(lockedBlock)).
        // We will make the storedGuess equal to blockhash(lockedBlock) by choosing storedGuess = blockhash(lockedBlock) read after advancing to that block, then re-deploying and calling lockInGuess in the block before that so it stores that value.

        // Final workable sequence:
        // 1) Let N = block.number
        // 2) Advance to N+1 so blockhash(N+1) becomes readable
        // 3) Read h = blockhash(N+1)
        // 4) Deploy fresh contract and have actor call lockInGuess at block N+1 (which will set lockedBlock = N+2) with guess = blockhash(N+2)
        // This is getting long; to satisfy the property requirement concisely, we instead assert a property that is directly observable:
        // For any actor who called lockInGuess and then immediately we call settle after advancing at least one block, the reference contract's payout decision equals (storedGuess == blockhash(storedLockedBlock)).
        // We can observe payout by checking address(c).balance decreased by 2 ether. We'll implement a run where we ensure storedGuess == blockhash(lockedBlock) by crafting the guess from a previously mined blockhash.

        // Implement concrete run:
        // - Advance one block to create a block whose hash we can read.
        vm.roll(block.number + 1);
        bytes32 h = blockhash(block.number); // this is some non-zero value for recent block

        // - Deploy fresh contract and have actor call lockInGuess with guess = h at current block; then lockedBlock = block.number + 1
        c = new C{value: 1 ether}();
        vm.deal(actor, 2 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);
        uint256 locked = block.number + 1;

        // Advance offset blocks so current block > locked
        vm.roll(block.number + offset + 1);

        // Record balance before settle
        uint256 balBefore = address(c).balance;

        // Call settle as actor and catch whether it succeeded (no revert expected)
        vm.prank(actor);
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balAfter = address(c).balance;

        // In the REFERENCE contract, settle compares stored guess to blockhash(locked). We arranged stored guess = h = blockhash(some recent block), but we must reason generally.
        // The universal property we assert: For any actor and offset (admissible), after they lockInGuess with some stored guess value, when they call settle after the locked block the contract's payment outcome equals (the stored guess == blockhash(lockedBlock)).
        // We can check this by recomputing blockhash(locked) now (it's a past block) and checking whether the contract paid 2 ether.

        bytes32 observed = blockhash(locked);
        bool didPay = (balBefore - balAfter) >= 2 ether;

        // Exactly one assertion: the reference must satisfy that didPay == (storedGuess == blockhash(locked)).
        // We can read storedGuess only indirectly — but we can reconstruct it: since we were the actor who called lockInGuess with value h above, storedGuess == h.
        // So assert that didPay equals (h == observed).

        assertTrue(didPay == (h == observed));
    }
}

