pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address alice = address(0xA11CE);

    function setUp() public {
        // deploy reference contract (correct C)
        c = new C{value: 1 ether}();
    }

    // Fuzzed params: a block offset to choose when lockInGuess will set its target block,
    // and an arbitrary bytes32 guess value to store. The fuzzer will search values; keep
    // wide domain but avoid underflow when we compute target-1 in the mutant reasoning.
    function testFuzz_property(uint32 lockDelay, bytes32 guessHash) public {
        // admissible domain: lockDelay at least 1 so that target block > current block
        // and block numbers we use are within practical ranges. Keep wide otherwise.
        vm.assume(lockDelay > 0);

        // Fund alice so she can send 1 ether
        vm.deal(alice, 2 ether);

        // Alice will lock a guess valued `guessHash` and the contract will set guesses[alice].block = block.number + 1
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Determine the block that was stored: it should be current block + 1.
        uint256 lockedBlock = block.number + 1;

        // Advance to a block strictly greater than lockedBlock so settle() is allowed
        // We advance by lockDelay to give the fuzzer freedom; ensure we advance at least 1 block
        // (lockDelay >= 1 by assume). Use vm.roll to set block number deterministically.
        uint256 targetBlock = lockedBlock + lockDelay;
        vm.roll(targetBlock);

        // Inspect the blockhash of the lockedBlock as the reference observable value
        bytes32 refAnswer = blockhash(lockedBlock);

        // Call settle as alice and observe whether settle paid out by checking contract balance change.
        // Save balance before and after to observe payout (2 ether back on success).
        uint256 balBefore = address(c).balance;
        vm.prank(alice);
        // settle is non-payable and may succeed or simply do nothing; we just call it
        c.settle();
        uint256 balAfter = address(c).balance;

        // The general rule (single assertion): For the correct contract, whether settle paid
        // equals (storedGuess == blockhash(lockedBlock)). We observe payout by checking
        // that contract lost 2 ether (payout occurred) iff guessHash == refAnswer.
        bool paid = (balBefore - balAfter) == 2 ether;

        // This assertion must hold for the reference implementation for ALL admissible inputs.
        // The mutant that reads blockhash(lockedBlock - 1) will in some cases make `paid` differ
        // from (guessHash == refAnswer), which the fuzzer can find.
        assertTrue(paid == (guessHash == refAnswer));
    }
}
